import { SEMANTIC_GOLDEN_PG16 } from './semantic-golden.pg16';

/**
 * The reviewed semantic posture per PostgreSQL major (generated by scripts/check-semantic-posture.ts --write from a
 * migrations-only owner-login database). A major with no entry is refused in production at boot (D4: unsupported major)
 * and only warned about elsewhere. PG18: add `18: SEMANTIC_GOLDEN_PG18` once generated and reviewed on PG18 (pg_get_expr
 * deparse may differ between majors, so one golden per major).
 */
export const SEMANTIC_GOLDEN_BY_MAJOR: Readonly<Record<number, readonly string[]>> = Object.freeze({
  16: SEMANTIC_GOLDEN_PG16,
});
